#!/usr/bin/env node
/**
 * FRIDAY — commit provenance.
 *
 * Fails when a commit in a git range names an assistant as author, committer,
 * or Co-authored-by, or when the message says it was generated by a tool.
 * The repository's own automation identities are allowed.
 *
 *   node scripts/check-provenance.cjs origin/main
 *   node scripts/check-provenance.cjs <base>..<head>
 *
 * A missing base ref exits 2. An empty range exits 0.
 */
"use strict";

const { execFileSync } = require("node:child_process");

const ALLOWED_NAMES = new Set([
  "friday-ci",
  "friday-release",
  "FRIDAY Repository Control",
  "FRIDAY Main Safety",
]);

const ASSISTANT_NAME =
  /\b(cursor|claude|anthropic|openai|copilot|codex|gemini|lovable|windsurf|chatgpt|aider|cline)\b|\[bot\]/i;
const ASSISTANT_EMAIL = /@(?:anthropic|cursor|openai)\.com|cursoragent|noreply@anthropic\.com/i;
const GENERATED = /generated with|🤖/i;
const COAUTHOR =
  /^co-authored-by:.*(?:noreply@anthropic\.com|@cursor\.com|@openai\.com|cursoragent|\b(?:cursor|claude|chatgpt|copilot|codex|lovable|windsurf|aider|cline|gemini|bolt|replit)\b|\[bot\])/i;

function git(args, cwd) {
  return execFileSync("git", args, {
    cwd,
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
  });
}

function assistantIdentity(name, email) {
  if (ALLOWED_NAMES.has(String(name || "").trim())) return false;
  return ASSISTANT_NAME.test(name || "") || ASSISTANT_EMAIL.test(email || "");
}

function problemsIn(sha, author, authorEmail, committer, committerEmail, body) {
  const problems = [];
  if (assistantIdentity(author, authorEmail)) {
    problems.push(`${sha} author ${author} <${authorEmail}>`);
  }
  if (assistantIdentity(committer, committerEmail)) {
    problems.push(`${sha} committer ${committer} <${committerEmail}>`);
  }
  if (GENERATED.test(body || "")) problems.push(`${sha} message says it was generated`);
  for (const line of String(body || "").split(/\r?\n/)) {
    if (COAUTHOR.test(line)) problems.push(`${sha} ${line.trim()}`);
  }
  return problems;
}

function checkRange(base, cwd = process.cwd()) {
  const spec = String(base || "").includes("..") ? String(base) : `${base}..HEAD`;
  let hashes = "";
  try {
    hashes = git(["rev-list", spec], cwd);
  } catch (error) {
    const detail = String(error.stderr || error.message || error).trim();
    return { ok: false, missing: true, problems: [detail || `cannot read ${spec}`] };
  }
  const problems = [];
  for (const sha of hashes
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean)) {
    const author = git(["show", "-s", "--format=%an", sha], cwd).trim();
    const authorEmail = git(["show", "-s", "--format=%ae", sha], cwd).trim();
    const committer = git(["show", "-s", "--format=%cn", sha], cwd).trim();
    const committerEmail = git(["show", "-s", "--format=%ce", sha], cwd).trim();
    const body = git(["show", "-s", "--format=%B", sha], cwd);
    problems.push(...problemsIn(sha, author, authorEmail, committer, committerEmail, body));
  }
  return { ok: problems.length === 0, missing: false, problems };
}

function main() {
  const base = process.argv[2];
  if (!base) {
    console.error("usage: node scripts/check-provenance.cjs <base-ref-or-range>");
    process.exit(2);
  }
  const result = checkRange(base, process.cwd());
  if (result.missing) {
    console.error(result.problems.join("\n"));
    process.exit(2);
  }
  if (!result.ok) {
    console.error(result.problems.join("\n"));
    process.exit(1);
  }
  console.log(`provenance ok (${base})`);
}

module.exports = { checkRange, problemsIn, assistantIdentity };

if (require.main === module) main();
